import { useState } from "react";

const toF = (c) => (c * 9) / 5 + 32;
const toC = (f) => ((f - 32) * 5) / 9;

function TempInput({ label, value, onChange }) {
  return (
    <label>
      {label}
      <input inputMode="decimal" value={value} onChange={(e) => onChange(e.target.value)} />
    </label>
  );
}

export function Calculator() {
  // Source of truth: last typed text and its box.
  const [temp, setTemp] = useState({ scale: "c", text: "20" });
  const n = Number(temp.text);
  const round = (x) => String(Math.round(x * 10) / 10);
  const celsius = temp.scale === "c" ? temp.text : round(toC(n));
  const fahrenheit = temp.scale === "f" ? temp.text : round(toF(n));

  return (
    <>
      <TempInput label="Celsius" value={celsius} onChange={(text) => setTemp({ scale: "c", text })} />
      <TempInput label="Fahrenheit" value={fahrenheit} onChange={(text) => setTemp({ scale: "f", text })} />
    </>
  );
}
